// Offline knowledge of the Google Ads object model.
//
// Core 1 of the two-core design: the agent designs a whole campaign — every
// field, every option — with **no network access at all**. Everything here
// reads server/google-ads-schema.json, generated by scripts/build-ads-schema.mjs
// from Google's own discovery document, so the field list and the enum values
// are Google's rather than something a model remembered.
//
// Nothing in this file makes a request.

import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const SCHEMA_PATH = path.join(path.dirname(fileURLToPath(import.meta.url)), "google-ads-schema.json");

/** @type {{apiVersion: string, generatedAt: string, roots: Record<string,string>, types: Record<string, {description: string, fields: Record<string, any>}>}} */
const schema = JSON.parse(readFileSync(SCHEMA_PATH, "utf8"));

export const API_VERSION = schema.apiVersion;
export const ROOT_RESOURCES = Object.keys(schema.roots);

/**
 * Discovery does not mark fields required, and Google's own errors for a missing
 * one are famously opaque ("The required field was not present"). These are the
 * ones learned from real rejections, so a plan fails locally with a useful
 * message instead of remotely with a useless one.
 */
export const REQUIRED_FIELDS = {
  CampaignBudget: ["name", "amountMicros"],
  Campaign: ["name", "advertisingChannelType", "campaignBudget", "containsEuPoliticalAdvertising"],
  AdGroup: ["name", "campaign"],
  AdGroupCriterion: ["adGroup"],
  AdGroupAd: ["adGroup", "ad"],
  AssetGroup: ["name", "campaign"],
  CampaignCriterion: ["campaign"],
};

/** Plural path segments for temp resource names, which discovery does not carry. */
export const RESOURCE_PATHS = {
  CampaignBudget: "campaignBudgets",
  Campaign: "campaigns",
  CampaignCriterion: "campaignCriteria",
  AdGroup: "adGroups",
  AdGroupCriterion: "adGroupCriteria",
  AdGroupAd: "adGroupAds",
  AssetGroup: "assetGroups",
};

/** mutateOperations key for each resource. */
export const OPERATION_KEYS = {
  CampaignBudget: "campaignBudgetOperation",
  Campaign: "campaignOperation",
  CampaignCriterion: "campaignCriterionOperation",
  AdGroup: "adGroupOperation",
  AdGroupCriterion: "adGroupCriterionOperation",
  AdGroupAd: "adGroupAdOperation",
  AssetGroup: "assetGroupOperation",
};

/** Order matters: a campaign cannot reference a budget that is created after it. */
export const CREATE_ORDER = [
  "CampaignBudget",
  "Campaign",
  "CampaignCriterion",
  "AssetGroup",
  "AdGroup",
  "AdGroupCriterion",
  "AdGroupAd",
];

export function typeOf(name) {
  return schema.types[name] || null;
}

export function resolveRoot(resource) {
  const key = schema.roots[resource] ? resource : Object.keys(schema.roots).find((r) => r.toLowerCase() === String(resource).toLowerCase());
  return key ? { name: key, typeName: schema.roots[key] } : null;
}

/**
 * Everything the agent needs to fill in one resource: field names, types, and
 * for enums every permitted value with Google's description of it.
 * @param {string} resource e.g. "Campaign"
 * @param {{ field?: string }} [options] drill into one field's nested type
 */
export function describeResource(resource, { field } = {}) {
  const root = resolveRoot(resource);
  if (!root) {
    throw new Error(`Unknown resource "${resource}". Known: ${ROOT_RESOURCES.join(", ")}.`);
  }
  let typeName = root.typeName;
  let label = root.name;

  if (field) {
    const parent = typeOf(typeName);
    const def = parent?.fields?.[field];
    if (!def) throw new Error(`${root.name} has no field "${field}".`);
    const ref = def.ref || def.items?.ref;
    if (!ref) {
      // A scalar or enum: describe the field itself rather than a nested type.
      return { resource: root.name, field, definition: def, fields: null, required: [] };
    }
    typeName = ref;
    label = `${root.name}.${field}`;
  }

  const type = typeOf(typeName);
  if (!type) throw new Error(`No schema for type "${typeName}".`);
  return {
    resource: label,
    typeName,
    description: type.description,
    fields: type.fields,
    required: field ? [] : REQUIRED_FIELDS[root.name] || [],
  };
}

const REF_RE = /^@([A-Za-z0-9_-]+)$/;

function checkValue(def, value, where, errors, refs) {
  if (value === null || value === undefined) return;

  // "@something" is a plan-local reference, resolved to a temp resource name at
  // submit time. Valid anywhere a resource name string is expected.
  if (typeof value === "string") {
    const match = REF_RE.exec(value);
    if (match) {
      if (!refs.has(match[1])) errors.push(`${where}: "@${match[1]}" does not match any entity ref in this plan.`);
      return;
    }
  }

  if (def.type === "enum") {
    const allowed = (def.values || []).map((v) => v.value);
    if (!allowed.includes(value)) {
      errors.push(`${where}: "${value}" is not valid. Allowed: ${allowed.join(", ")}.`);
    }
    return;
  }
  if (def.type === "array") {
    if (!Array.isArray(value)) {
      errors.push(`${where}: expected an array.`);
      return;
    }
    value.forEach((item, index) => {
      const itemDef = def.items?.ref ? { type: "object", ref: def.items.ref } : def.items || { type: "string" };
      checkValue(itemDef, item, `${where}[${index}]`, errors, refs);
    });
    return;
  }
  if (def.type === "object" && def.ref) {
    if (typeof value !== "object" || Array.isArray(value)) {
      errors.push(`${where}: expected an object.`);
      return;
    }
    checkFields(def.ref, value, where, errors, refs);
    return;
  }
  if (def.type === "boolean" && typeof value !== "boolean") errors.push(`${where}: expected true or false.`);
  if (def.type === "number" || def.type === "integer") {
    if (typeof value !== "number" && !(typeof value === "string" && /^-?\d+$/.test(value))) {
      errors.push(`${where}: expected a number.`);
    }
  }
}

function checkFields(typeName, values, where, errors, refs) {
  const type = typeOf(typeName);
  if (!type) {
    errors.push(`${where}: no schema for type "${typeName}".`);
    return;
  }
  for (const [name, value] of Object.entries(values)) {
    const def = type.fields[name];
    if (!def) {
      const near = Object.keys(type.fields)
        .filter((f) => f.toLowerCase().startsWith(String(name).slice(0, 3).toLowerCase()))
        .slice(0, 6);
      errors.push(`${where}.${name}: not a field of ${typeName}.${near.length ? ` Did you mean: ${near.join(", ")}?` : ""}`);
      continue;
    }
    checkValue(def, value, `${where}.${name}`, errors, refs);
  }
}

/**
 * Validates a whole campaign plan offline: known resources, real field names,
 * legal enum values, resolvable @refs, and the required fields Google will
 * otherwise reject opaquely. Returns every problem at once rather than the first.
 *
 * @param {{entities?: Array<{ref?: string, resource?: string, fields?: object}>}} plan
 * @returns {{ok: boolean, errors: string[], entities: number}}
 */
export function validatePlan(plan) {
  const errors = [];
  const entities = Array.isArray(plan?.entities) ? plan.entities : null;
  if (!entities) return { ok: false, errors: ["The plan needs an 'entities' array."], entities: 0 };
  if (!entities.length) return { ok: false, errors: ["The plan has no entities."], entities: 0 };

  const refs = new Set();
  for (const entity of entities) {
    if (!entity?.ref) errors.push("Every entity needs a unique 'ref' so others can point at it.");
    else if (refs.has(entity.ref)) errors.push(`Duplicate ref "${entity.ref}".`);
    else refs.add(entity.ref);
  }

  entities.forEach((entity, index) => {
    const where = `entities[${index}]${entity?.ref ? ` (@${entity.ref})` : ""}`;
    const root = entity?.resource ? resolveRoot(entity.resource) : null;
    if (!root) {
      errors.push(`${where}: unknown resource "${entity?.resource}". Known: ${ROOT_RESOURCES.join(", ")}.`);
      return;
    }
    const fields = entity.fields;
    if (!fields || typeof fields !== "object") {
      errors.push(`${where}: needs a 'fields' object.`);
      return;
    }
    checkFields(root.typeName, fields, where, errors, refs);

    for (const required of REQUIRED_FIELDS[root.name] || []) {
      if (fields[required] === undefined) errors.push(`${where}: missing required field "${required}".`);
    }

    // ENABLED is a legal enum value, so the schema check above passes it. The
    // safety rule is separate, and belongs here so a plan is rejected while it
    // is still being designed rather than at submit time.
    if (fields.status !== undefined && String(fields.status).toUpperCase() !== "PAUSED") {
      errors.push(
        `${where}.status: "${fields.status}" is not allowed. Plans may only create paused entities — omit status entirely and PAUSED is set for you.`,
      );
    }
  });

  return { ok: errors.length === 0, errors, entities: entities.length };
}
